sys_script.script:
(function executeRule(current, previous) {
    var existing = new GlideRecord('x_snc_ai_sdlc_story_manifest');
    existing.addQuery('story', current.getUniqueValue());
    existing.setLimit(1);
    existing.query();
    if (existing.next()) return;

    var manifest = new GlideRecord('x_snc_ai_sdlc_story_manifest');
    manifest.initialize();
    manifest.setValue('story',                current.getUniqueValue());
    manifest.setValue('orchestration_status', 'pending');
    manifest.insert();
})(current, previous);
